 Q(4, "K", "Seorang pegawai bergaji bruto Rp20.000.000 sebulan. Biaya jabatan bulan itu menurut modul:", "Rp1.000.000", "Rp500.000", "Rp6.000.000", "Rp100.000", "b", "5% dari 20.000.000 adalah 1.000.000, tetapi dibatasi maksimal Rp500.000 per bulan."),
 Q(4, "K", "Menurut modul, tambahan PTKP untuk setiap tanggungan adalah:", "Rp4,5 juta, paling banyak tiga orang", "Rp54 juta tanpa batas", "Rp1 juta paling banyak satu orang", "Tidak ada tambahan", "a", "PMK 101/PMK.010/2016 yang dikutip modul: tambahan Rp4,5 juta per tanggungan, maksimal tiga orang."),
 Q(4, "K", "Yang termasuk kewajiban pemotong PPh 21 menurut modul:", "Menghitung, memotong, menyetorkan, melaporkan, dan memberi bukti potong", "Hanya memberi ucapan terima kasih", "Hanya menyimpan uang", "Menghapus catatan pegawai", "a", "Modul menyebut kewajiban pemotong termasuk memberikan bukti pemotongan."),
 Q(4, "A", "Pegawai menyerahkan kepada pemotong:", "Surat pernyataan jumlah tanggungan keluarga", "Rapor SMP", "Foto kendaraan", "Daftar belanja", "a", "Kewajiban wajib pajak menurut modul: menyerahkan surat pernyataan jumlah tanggungan keluarga."),
 Q(5, "A", "TER PPh 21 mulai berlaku pada:", "Januari 2024", "Januari 2010", "April 2022", "Desember 2023", "a", "Artikel DJP: TER mulai berlaku Januari 2024."),
 Q(5, "K", "Dasar hukum TER PPh 21 adalah:", "PP Nomor 58 Tahun 2023 dan PMK Nomor 168 Tahun 2023", "UU Nomor 42 Tahun 2009 saja", "PMK 71 Tahun 2022 saja", "UU 28 Tahun 2009", "a", "Artikel DJP menyebut PP 58/2023 dan PMK 168/2023 beserta Pasal 21 UU PPh."),
 Q(5, "K", "Pegawai berstatus K/1 memakai kategori:", "TER A", "TER B", "TER C", "Tidak memakai TER", "b", "TER B untuk TK/2, TK/3, K/1, dan K/2."),
 Q(5, "K", "Pada masa pajak Januari sampai November, pemotong memakai:", "Tarif TER", "Tarif Pasal 17 saja", "Tarif nol untuk semua", "Tarif harian untuk semua pegawai tetap", "a", "TER dipakai Januari sampai November; Desember dihitung dengan tarif Pasal 17 ayat (1) huruf a."),
 Q(5, "K", "TER harian 0% berlaku untuk penghasilan bruto harian:", "Sampai Rp450.000", "Di atas Rp2.500.000", "Tepat Rp3.000.000", "Berapa pun jumlahnya", "a", "Artikel DJP: 0% bila penghasilan bruto harian tidak lebih dari Rp450.000."),
